<?php
namespace App\Http\Requests;
use Illuminate\Foundation\Http\FormRequest;
class StoreBatchRequest extends FormRequest { public function authorize(): bool{return true;} public function rules(): array{return ['notifications'=>['required','array','min:1','max:1000'],'notifications.*.recipient'=>['required','string','max:320'],'notifications.*.channel'=>['required','in:sms,email,push'],'notifications.*.content'=>['required','string','max:10000'],'notifications.*.priority'=>['sometimes','in:high,normal,low'],'notifications.*.idempotency_key'=>['sometimes','nullable','string','max:255'],'notifications.*.scheduled_at'=>['sometimes','nullable','date','after_or_equal:now']];} public function withValidator($validator): void { $validator->after(function($v){$keys=[];foreach($this->input('notifications',[]) as $i=>$item){if(!is_array($item))continue;if(isset($item['idempotency_key']) && $item['idempotency_key']!==''){if(isset($keys[$item['idempotency_key']]))$v->errors()->add("notifications.{$i}.idempotency_key",'Duplicate idempotency key within the same batch.');$keys[$item['idempotency_key']]=true;}$channel=$item['channel']??'';$content=(string)($item['content']??'');$limit=match($channel){'sms'=>1600,'push'=>4096,default=>10000};if(mb_strlen($content)>$limit)$v->errors()->add("notifications.{$i}.content","Content exceeds the {$channel} limit of {$limit} characters.");if($channel==='email' && !filter_var($item['recipient']??'',FILTER_VALIDATE_EMAIL))$v->errors()->add("notifications.{$i}.recipient",'A valid email address is required for email notifications.');}});} }
